-- C-071b2: 96 more five-star hotels in the big cities (London, Paris, Dubai, New York, Rome,
-- the Maldives, …), ranked like C-155 (Tripadvisor's typical minimum price, ≥ 200 reviews, rating
-- ≥ 4.3); business hotels and serviced apartments left out by hand. Every hotel returned live
-- prices from Xotelo (Rixos The Palm never did and was left out); photos are the hotels' own via
-- LiteAPI (D-51), checked by eye. Google Hotels ids come on demand (C-153). Idempotent.
insert into public.hotels
  (slug, name, city_id, lat, lng, xotelo_key, liteapi_id, image_url, image_credit,
   image_source_url, active)
select v.slug, v.name, c.id, v.lat, v.lng, v.xotelo_key,
       case when exists (select 1 from public.hotels h where h.liteapi_id = v.liteapi_id)
            then null else v.liteapi_id end,
       v.image_url, v.image_credit, v.image_source_url, true
